from pathlib import Path
import re,base64,shutil,json
D=Path(__file__).resolve().parent.parent
source=next(Path('/Users/max/CURSOR/1. ЛИЧНОЕ').rglob('Слово_пастора_Андрея*.html')).read_text()
fonts='\n'.join(re.findall(r'@font-face\{[^}]+\}',source))
def datafile(name,mime):
 return 'data:'+mime+';base64,'+base64.b64encode((D/'_сборка'/'figma'/name).read_bytes()).decode()
leaves=datafile('background.png','image/png')
mark=datafile('mark.svg','image/svg+xml')
