ids={'shepherds':'3a854efc-48d6-44af-889c-2881e47a3698','wells':'e180b591-40cd-4ae4-ab4f-8711cc2203fc','abigail':'88934c75-73c9-4c7d-aebb-9f63aa1592a0','father':'61e01f4d-24a6-4e89-a7a1-851f667ce358','preparations':'79316820-d6ae-45ac-b4a1-5f96cc56375c'}
imgs={}
for name,id in ids.items():
 p=Path('/Users/max/.codex/generated_images/01a192d2-8164-7cf3-88c5-60cd9ba6eb3f')/f'exec-{id}.png'
 shutil.copy2(p,D/'_сборка'/f'{name}.png')
