brand=f'<div class="brand"><span><img class="outer-mark" src="{mark}"><img class="inner-mark" src="{markin}"></span><img class="word" src="{word}"></div>'
slides=[]
def add(content,kind='',chapter='КОНФЛИКТ И ПРИМИРЕНИЕ'):
 n=len(slides)+1
 slides.append(f'<section class="slide {kind}"><img class="texture" src="{leaves}" alt=""><header>{brand}<span>{chapter}</span></header><main>{content}</main><footer><span>ОКСАНА ПУРШАГА</span><span>{n:02d} / 15</span></footer></section>')
def quote(title,text,ref,art=None,note='',kind='',chapter='БИБЛЕЙСКИЕ ИСТОРИИ'):
 content=f'<div class="copy"><h2>{title}</h2>'+(f'<p class="context">{note}</p>' if note else '')+f'<blockquote>«{text}»</blockquote><p class="ref">{ref}</p></div>'
 if art: content+=f'<figure><img src="{imgs[art]}"></figure>'
 add(content,('illustrated ' if art else 'quotation ')+kind,chapter)
add('<div class="cover"><p class="eyebrow">ОКСАНА ПУРШАГА</p><h1>Конфликт<br><em>и примирение</em></h1><div class="rule"></div></div>','cover-slide','')
add('<p class="eyebrow">ПОНЯТИЕ</p><h2>Что такое конфликт</h2><p class="definition"><strong>Конфликт</strong> — это столкновение противоположных целей, интересов, мнений, взглядов или позиций в социальном взаимодействии.</p>','definition-slide','О КОНФЛИКТЕ')
add('<h2>Основные признаки</h2><div class="rows">'+''.join(f'<div class="row"><span class="num">0{i}</span><h3>{t}</h3><p>{v}</p></div>' for i,t,v in [(1,'Биполярность','Как минимум две противоположные стороны или точки зрения.'),(2,'Активность','Действия участников для преодоления сопротивления или отстаивания своих интересов.'),(3,'Противоречие','Несовместимость целей, ценностей или ресурсов.')])+'</div>','','О КОНФЛИКТЕ')
add('<h2>Виды конфликтов</h2><p class="eyebrow below">ПО МАСШТАБУ И УЧАСТНИКАМ</p><div class="columns">'+''.join(f'<div><span class="num">0{i}</span><h3>{t}</h3><p>{v}</p></div>' for i,t,v in [(1,'Внутриличностные','Конфликт с самим собой, выбор между ценностями.'),(2,'Межличностные','Между двумя людьми.'),(3,'Межгрупповые','Между командами, отделами, социальными группами или государствами.')])+'</div><div class="sphere"><span>ПО СФЕРЕ ДЕЯТЕЛЬНОСТИ</span><p>Политические · Экономические · Социальные<br>Трудовые · Бытовые</p></div>','types','О КОНФЛИКТЕ')
quote('Конфликт<br>между пастухами','И был спор между пастухами скота Аврамова и между пастухами скота Лотова; и Хананеи и Ферезеи жили тогда в той земле.','Бытие 13:7','shepherds')
quote('Кто должен первым<br>оставить конфликт?','И сказал Аврам Лоту: да не будет раздора между мною и тобою, и между пастухами моими и пастухами твоими, ибо мы родственники;','Бытие 13:8',kind='accent')
quote('Зависть и конфликт','И все колодези, которые выкопали рабы отца его при жизни отца его Авраама, Филистимляне завалили и засыпали землею.','Бытие 26:15','wells','Филистимляне завидовали благополучию Исаака.<br><span style="white-space:nowrap">Быт. 26:12–14</span>')
quote('Авигея','Тогда Авигея поспешно взяла двести хлебов, и два меха с вином, и пять овец приготовленных, и пять мер сушёных зёрен, и сто связок изюму, и двести связок смокв, и навьючила на ослов,','1 Царств 25:18','preparations','Навал отказал Давиду в помощи. 1 Цар. 25:10–11',kind='dense')
quote('Авигея перед Давидом','Когда Авигея увидела Давида, то поспешила сойти с осла и пала пред Давидом на лице своё и поклонилась до земли;','1 Царств 25:23','abigail')
quote('Зависть, споры<br>и разногласия','потому что вы ещё плотские. Ибо если между вами зависть, споры и разногласия, то не плотские ли вы? и не по человеческому ли обычаю поступаете?','1 Коринфянам 3:3',chapter='ОТНОШЕНИЯ И СЕРДЦЕ')
quote('По Своей милости','Он спас нас не по делам праведности, которые бы мы сотворили, а по Своей милости, банею возрождения и обновления Святым Духом,','Титу 3:5',kind='accent',chapter='МИЛОСТЬ · ДОБРЫЕ ДЕЛА · МИР')
quote('Быть прилежными<br>к добрым делам','Слово это верно; и я желаю, чтобы ты подтверждал о сём, дабы уверовавшие в Бога старались быть прилежными к добрым делам: это хорошо и полезно человекам.','Титу 3:8',chapter='МИЛОСТЬ · ДОБРЫЕ ДЕЛА · МИР')
quote('Удаляться<br>от бесполезных споров','Глупых же состязаний и родословий, и споров и распрей о законе удаляйся, ибо они бесполезны и суетны.','Титу 3:9',kind='accent',chapter='МИЛОСТЬ · ДОБРЫЕ ДЕЛА · МИР')
quote('Мирись скорее','Мирись с соперником твоим скорее, пока ты ещё на пути с ним, чтобы соперник не отдал тебя судье, а судья не отдал бы тебя слуге, и не ввергли бы тебя в темницу;','Матфея 5:25',chapter='ПРИМИРЕНИЕ')
add(f'<div class="copy"><p class="eyebrow">КТО ПРОСИТ ПРОЩЕНИЯ?</p><h2 class="final-words">Тот, кто хочет<br><em>сохранить<br>отношения</em></h2></div><figure><img src="{imgs["father"]}"></figure>','illustrated closing','ПРИМИРЕНИЕ')
